import{_ as e,o as s,c as t,a3 as n}from"./chunks/framework.6_aCw6yF.js";const u=JSON.parse('{"title":"Java 集合","description":"Collection 与 Map 的常见实现，以及 ArrayList、HashMap 等容器的底层结构。","frontmatter":{"title":"Java 集合","description":"Collection 与 Map 的常见实现，以及 ArrayList、HashMap 等容器的底层结构。","date":"2026-11-20T00:00:00.000Z","category":"匠心造物","subCategory":"Java 面试","tags":["面试","Java","集合"],"author":"闲生"},"headers":[],"relativePath":"posts/create/interview/java-collection.md","filePath":"posts/create/interview/java-collection.md"}'),i={name:"posts/create/interview/java-collection.md"};function p(l,a,r,o,c,h){return s(),t("div",null,[...a[0]||(a[0]=[n(`<h1 id="java-集合" tabindex="-1">Java 集合 <a class="header-anchor" href="#java-集合" aria-label="Permalink to &quot;Java 集合&quot;">​</a></h1><blockquote><p>容器主要包括 Collection 和 Map 两种，Collection 存储着对象的集合，而 Map 存储着键值对(两个对象)的映射表。</p></blockquote><h2 id="collection" tabindex="-1">Collection <a class="header-anchor" href="#collection" aria-label="Permalink to &quot;Collection&quot;">​</a></h2><h3 id="集合有哪些类" tabindex="-1">集合有哪些类？ <a class="header-anchor" href="#集合有哪些类" aria-label="Permalink to &quot;集合有哪些类？&quot;">​</a></h3><ul><li>Set <ul><li>TreeSet 基于红黑树实现，支持有序性操作，例如根据一个范围查找元素的操作。但是查找效率不如 HashSet，HashSet 查找的时间复杂度为 O(1)，TreeSet 则为 O(logN)。</li><li>HashSet 基于哈希表实现，支持快速查找，但不支持有序性操作。并且失去了元素的插入顺序信息，也就是说使用 Iterator 遍历 HashSet 得到的结果是不确定的。</li><li>LinkedHashSet 具有 HashSet 的查找效率，且内部使用双向链表维护元素的插入顺序。</li></ul></li><li>List <ul><li>ArrayList 基于动态数组实现，支持随机访问。</li><li>Vector 和 ArrayList 类似，但它是线程安全的。</li><li>LinkedList 基于双向链表实现，只能顺序访问，但是可以快速地在链表中间插入和删除元素。不仅如此，LinkedList 还可以用作栈、队列和双向队列。</li></ul></li><li>Queue <ul><li>LinkedList 可以用它来实现双向队列。</li><li>PriorityQueue 基于堆结构实现，可以用它来实现优先队列。</li></ul></li></ul><h3 id="arraylist的底层" tabindex="-1">ArrayList的底层？ <a class="header-anchor" href="#arraylist的底层" aria-label="Permalink to &quot;ArrayList的底层？&quot;">​</a></h3><p>_ArrayList_实现了_List_接口，是顺序容器，即元素存放的数据与放进去的顺序相同，允许放入<code>null</code>元素，底层通过<strong>数组实现</strong>。除该类未实现同步外，其余跟_Vector_大致相同。每个_ArrayList_都有一个容量(capacity)，表示底层数组的实际大小，容器内存储元素的个数不能多于当前容量。当向容器中添加元素时，如果容量不足，容器会自动增大底层数组的大小。前面已经提过，Java泛型只是编译器提供的语法糖，所以这里的数组是一个Object数组，以便能够容纳任何类型的对象。</p><p><img src="https://cdn.jsdelivr.net/gh/jokerxian/pic/pics/6376401485.png" alt="ArrayList_base"></p><h3 id="arraylist自动扩容" tabindex="-1">ArrayList自动扩容？ <a class="header-anchor" href="#arraylist自动扩容" aria-label="Permalink to &quot;ArrayList自动扩容？&quot;">​</a></h3><p>每当向数组中添加元素时，都要去检查添加后元素的个数是否会超出当前数组的长度，如果超出，数组将会进行扩容，以满足添加数据的需求。数组扩容通过ensureCapacity(int minCapacity)方法来实现。在实际添加大量元素前，我也可以使用ensureCapacity来手动增加ArrayList实例的容量，以减少递增式再分配的数量。</p><p>数组进行扩容时，会将老数组中的元素重新拷贝一份到新的数组中，每次数组容量的增长大约是其原容量的1.5倍。这种操作的代价是很高的，因此在实际使用时，我们应该尽量避免数组容量的扩张。当我们可预知要保存的元素的多少时，要在构造ArrayList实例时，就指定其容量，以避免数组扩容的发生。或者根据实际需求，通过调用ensureCapacity方法来手动增加ArrayList实例的容量。</p><p><img src="https://cdn.jsdelivr.net/gh/jokerxian/pic/pics/06a5dc1570.png" alt="ArrayList_add"></p><h3 id="arraylist的fail-fast机制" tabindex="-1">ArrayList的Fail-Fast机制？ <a class="header-anchor" href="#arraylist的fail-fast机制" aria-label="Permalink to &quot;ArrayList的Fail-Fast机制？&quot;">​</a></h3><p>ArrayList也采用了快速失败的机制，通过记录modCount参数来实现。在面对并发的修改时，迭代器很快就会完全失败，而不是冒着在将来某个不确定时间发生任意不确定行为的风险。</p><h2 id="map" tabindex="-1">Map <a class="header-anchor" href="#map" aria-label="Permalink to &quot;Map&quot;">​</a></h2><h3 id="map有哪些类" tabindex="-1">Map有哪些类？ <a class="header-anchor" href="#map有哪些类" aria-label="Permalink to &quot;Map有哪些类？&quot;">​</a></h3><ul><li><code>TreeMap</code> 基于红黑树实现。</li><li><code>HashMap</code> 1.7基于哈希表实现，1.8基于数组+链表+红黑树。</li><li><code>HashTable</code> 和 HashMap 类似，但它是线程安全的，这意味着同一时刻多个线程可以同时写入 HashTable 并且不会导致数据不一致。它是遗留类，不应该去使用它。现在可以使用 ConcurrentHashMap 来支持线程安全，并且 ConcurrentHashMap 的效率会更高(1.7 ConcurrentHashMap 引入了分段锁, 1.8 引入了红黑树)。</li><li><code>LinkedHashMap</code> 使用双向链表来维护元素的顺序，顺序为插入顺序或者最近最少使用(LRU)顺序。</li></ul><h3 id="jdk7-hashmap如何实现" tabindex="-1">JDK7 HashMap如何实现？ <a class="header-anchor" href="#jdk7-hashmap如何实现" aria-label="Permalink to &quot;JDK7 HashMap如何实现？&quot;">​</a></h3><p>哈希表有两种实现方式，一种开放地址方式(Open addressing)，另一种是冲突链表方式(Separate chaining with linked lists)。<strong>Java7 _HashMap_采用的是冲突链表方式</strong>。</p><p><img src="https://cdn.jsdelivr.net/gh/jokerxian/pic/pics/67963b08a2.png" alt="HashMap_base"></p><p>从上图容易看出，如果选择合适的哈希函数，<code>put()</code>和<code>get()</code>方法可以在常数时间内完成。但在对_HashMap_进行迭代时，需要遍历整个table以及后面跟的冲突链表。因此对于迭代比较频繁的场景，不宜将_HashMap_的初始大小设的过大。</p><p>有两个参数可以影响_HashMap_的性能: 初始容量(inital capacity)和负载系数(load factor)。初始容量指定了初始<code>table</code>的大小，负载系数用来指定自动扩容的临界值。当<code>entry</code>的数量超过<code>capacity*load_factor</code>时，容器将自动扩容并重新哈希。对于插入元素较多的场景，将初始容量设大可以减少重新哈希的次数。</p><h3 id="jdk8-hashmap如何实现" tabindex="-1">JDK8 HashMap如何实现？ <a class="header-anchor" href="#jdk8-hashmap如何实现" aria-label="Permalink to &quot;JDK8 HashMap如何实现？&quot;">​</a></h3><p>根据 Java7 HashMap 的介绍，我们知道，查找的时候，根据 hash 值我们能够快速定位到数组的具体下标，但是之后的话，需要顺着链表一个个比较下去才能找到我们需要的，时间复杂度取决于链表的长度，为 O(n)。</p><p>为了降低这部分的开销，在 Java8 中，当链表中的元素达到了 8 个时，会将链表转换为红黑树，在这些位置进行查找的时候可以降低时间复杂度为 O(logN)。</p><p><img src="https://cdn.jsdelivr.net/gh/jokerxian/pic/pics/f42c4b4901.png" alt=""></p><h3 id="hashset是如何实现的" tabindex="-1">HashSet是如何实现的？ <a class="header-anchor" href="#hashset是如何实现的" aria-label="Permalink to &quot;HashSet是如何实现的？&quot;">​</a></h3><p>_HashSet_是对_HashMap_的简单包装，对_HashSet_的函数调用都会转换成合适的_HashMap_方法</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" tabindex="0"><code><span class="line"><span>//HashSet是对HashMap的简单包装</span></span>
<span class="line"><span>public class HashSet&lt;E&gt;</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>	......</span></span>
<span class="line"><span>	private transient HashMap&lt;E,Object&gt; map;//HashSet里面有一个HashMap</span></span>
<span class="line"><span>    // Dummy value to associate with an Object in the backing Map</span></span>
<span class="line"><span>    private static final Object PRESENT = new Object();</span></span>
<span class="line"><span>    public HashSet() {</span></span>
<span class="line"><span>        map = new HashMap&lt;&gt;();</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    ......</span></span>
<span class="line"><span>    public boolean add(E e) {//简单的方法转换</span></span>
<span class="line"><span>        return map.put(e, PRESENT)==null;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    ......</span></span>
<span class="line"><span>}</span></span></code></pre></div><h3 id="什么是weakhashmap" tabindex="-1">什么是WeakHashMap? <a class="header-anchor" href="#什么是weakhashmap" aria-label="Permalink to &quot;什么是WeakHashMap?&quot;">​</a></h3><p>我们都知道Java中内存是通过GC自动管理的，GC会在程序运行过程中自动判断哪些对象是可以被回收的，并在合适的时机进行内存释放。GC判断某个对象是否可被回收的依据是，<strong>是否有有效的引用指向该对象</strong>。如果没有有效引用指向该对象(基本意味着不存在访问该对象的方式)，那么该对象就是可回收的。这里的<strong>有效引用</strong> 并不包括<strong>弱引用</strong>。也就是说，<strong>虽然弱引用可以用来访问对象，但进行垃圾回收时弱引用并不会被考虑在内，仅有弱引用指向的对象仍然会被GC回收</strong>。</p><p>WeakHashMap 内部是通过弱引用来管理entry的，弱引用的特性对应到 WeakHashMap 上意味着什么呢？</p><p><em>WeakHashMap</em> 里的<code>entry</code>可能会被GC自动删除，即使程序员没有调用<code>remove()</code>或者<code>clear()</code>方法。</p><p><strong><em>WeakHashMap</em> 的这个特点特别适用于需要缓存的场景</strong>。在缓存场景下，由于内存是有限的，不能缓存所有对象；对象缓存命中可以提高系统效率，但缓存MISS也不会造成错误，因为可以通过计算重新得到。</p><hr><blockquote><p>本章整理自 <a href="https://pdai.tech/md/interview/x-interview.html" target="_blank" rel="noreferrer">pdai.tech《Java 全栈知识点问题汇总》</a>，仅作个人复习存档；图片已转存至自建图床，少数原图失效处保留了待补标记。</p></blockquote>`,36)])])}const b=e(i,[["render",p]]);export{u as __pageData,b as default};
